from ute_testline_configuration.ute_config import UTE_CONFIG, Host, FSMr4, IPHY, Pdu


class ConfigTranslator:
    def translate(self, tl):
        addr = tl.test_pc.default_ssh_connection_details.addr
        if len(tl.pdus) >= 1:
            pdu_type = type(tl.pdus[0]).__name__
        else:
            raise Exception('Multi PDU configuration not supported yet')
        try:
            AP_pdu_port = tl.ues[0].l1.common_units[0].pdu_port
        except Exception:
            raise Exception('Missing PDU port in Airphone configuration')
        try:
            gNB_pdu_port = tl.gnbs[0].dus[0].airscale.common_units[0].pdu_port
        except Exception:
            raise Exception('Missing PDU port in Airscale configuration')
        host = [Host(addr=addr)]
        iphy = [IPHY(pdu=Pdu(addr=AP_pdu_port.pdu.addr, port=AP_pdu_port.port_no, device=pdu_type))]
        fsm = [
            FSMr4(
                hw_type='FSIP',
                hw_version='A101',
                pdu=Pdu(addr=gNB_pdu_port.pdu.addr, port=gNB_pdu_port.port_no, device=pdu_type),
                fbip1=True,
                fbip2=False,
                fbip3=False,
            )
        ]
        tl_output = UTE_CONFIG(fsm=fsm, host=host, iphy=iphy)
        return tl_output

    def serialize(self, tl_output):
        txt = "from ute_testline_configuration.ute_config import UTE_CONFIG, Host, FSMr4, IPHY, Pdu\n\n"
        txt = txt + "host = [Host(addr='{}')]\n".format(tl_output.host.addr)
        txt = txt + "iphy = [IPHY(pdu=Pdu(addr='{}', port={}, device='{}'))]\n".format(
            tl_output.iphy.pdu.addr, tl_output.iphy.pdu.port, tl_output.iphy.pdu.device
        )
        txt = (
            txt + "fsm = [FSMr4(hw_type='FSIP', hw_version='A101', pdu=Pdu(addr='{}', port={}, "
            "device='{}'), fbip1=True, fbip2=False, fbip3=False)]\n".format(
                tl_output.fsm.pdu.addr, tl_output.fsm.pdu.port, tl_output.fsm.pdu.device
            )
        )
        txt = txt + "tl = UTE_CONFIG(fsm=fsm, host=host, iphy=iphy)\n"
        return txt
